#!/usr/bin/env python3
"""Execute the original relocated MADDWD against its original constant bytes."""
import argparse,hashlib,json,os,pathlib,struct,subprocess
import pefile
from sse_build_inputs import sse_inputs
R=pathlib.Path(__file__).resolve().parents[1];ap=argparse.ArgumentParser();ap.add_argument('--simulator-device');a=ap.parse_args();out=R/'generated/sse/relocated-maddwd'/(a.simulator_device or 'macos');out.mkdir(parents=True,exist_ok=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();(out/'result.json').write_text(json.dumps({'pass':False,'state':'running'})+'\n')
if a.simulator_device:
 inventory=json.loads(subprocess.check_output(['xcrun','simctl','list','devices','booted','--json'],text=True));assert [d['udid'] for rows in inventory['devices'].values() for d in rows if d['state']=='Booted']==[a.simulator_device]
original=R/'ref/product/IFC22.dll';p=pefile.PE(str(original));code=bytes.fromhex('c5fdf505003a1410');assert p.get_data(0xc5bdc,8)==code;constant=p.get_data(0x143a00,32);assert len(constant)==32
raw=bytearray(original.read_bytes()[:0x400]);header=struct.unpack_from('<I',raw,0x3c)[0];optional=header+24;section=optional+224;struct.pack_into('<H',raw,header+6,2);struct.pack_into('<H',raw,header+22,0x103)
for off,value in [(4,512),(8,4096),(16,0x1000),(56,0x144000),(60,0x400)]:struct.pack_into('<I',raw,optional+off,value)
raw[optional+96:optional+224]=bytes(128);raw[section:]=bytes(len(raw)-section);struct.pack_into('<8s6I2HI',raw,section,b'.text\0\0\0',9,0x1000,512,0x400,0,0,0,0,0x60000020);struct.pack_into('<8s6I2HI',raw,section+40,b'.rdata\0\0',4096,0x143000,4096,0x600,0,0,0,0,0x40000040);data=bytearray(4096);data[0xa00:0xa20]=constant;raw+=code+b'\xc3'+bytes(503)+data;(out/'fixture.exe').write_bytes(raw);(out/'relocations.csv').write_text('0x10001004,0x10143a00,\n');(out/'global_aliases.sci').write_text('loc_10001000,fixture_0\n')
fixture=pefile.PE(data=bytes(raw));assert fixture.get_data(0x1000,8)==code and fixture.get_data(0x143a00,32)==constant
srw=R/'generated/tools/SRW-tribes/SRW.exe';build=json.loads((srw.parent/'tribes-build.json').read_text());assert sha(srw)==build['srw_sha256'] and sha(R/'scripts/patches/srw-tribes.patch')==build['patch_sha256'];run=subprocess.run([str(srw),'fixture.exe','fixture.llasm'],cwd=out,env={k:v for k,v in {**os.environ,'TRIBES_SRW_FULL_FLAGS':'1'}.items() if k!='HALOPAD_SRW_DIAG'},capture_output=True,text=True,timeout=60);(out/'srw.log').write_text(run.stdout+run.stderr);assert not run.returncode,(run.stdout,run.stderr)
body=(out/'seg01_code.llinc').read_text().split('global c_fixture_0\n')[1].split(';ret\n')[0];assert 'mov tmpadr, loc_10143A00' in body and 'call tb_avx_maddaddmem $, 1, 1, 0, 0, tmpadr' in body
source=out/'native.llasm';source.write_text('include tribes_sse.llinc\nproc relocated_maddwd public\n'+body+'endp\ndatasegment .relocation constant\ndlabel relocation_backing global\n'+'db 165\n'*17+'dlabel loc_10143A00 global\n'+''.join('db '+str(v)+'\n' for v in constant)+'db 165\n'*48+'endd\n');llasm=R/'generated/tools/llasm/llasm';ir=out/'native.ll';subprocess.run([str(llasm),'-m64','-ptrofs','-O2','-I',str(R/'port/llasm-support'),'-o',str(ir),str(source)],check=True)
platform='simulator' if a.simulator_device else 'macos';sdkname='iphonesimulator' if a.simulator_device else 'macosx';target='arm64-apple-ios16-simulator' if a.simulator_device else 'arm64-apple-macos12';sdk=subprocess.check_output(['xcrun','--sdk',sdkname,'--show-sdk-path'],text=True).strip();math=sse_inputs(platform);c=R/'tests/relocated_maddwd_test.c';helper=R/'port/llasm-support/tribes_sse.c';exe=out/'native';subprocess.run(['clang','-target',target,'-isysroot',sdk,'-O2','-DPTROFS_64BIT','-Wall','-Wextra','-Werror','-Wno-override-module']+math['compile_flags']+[str(ir),str(c),str(helper)]+math['sources']+math['libraries']+['-o',str(exe)],check=True);run=subprocess.run(['xcrun','simctl','spawn',a.simulator_device,str(exe)] if a.simulator_device else [str(exe)],capture_output=True,text=True,timeout=60);assert not run.returncode and run.stdout.startswith('PASS:') and not run.stderr,(run.stdout,run.stderr);(out/'run.log').write_text(run.stdout)
paths=[pathlib.Path(__file__).resolve(),c,helper]+[R/'port/llasm-support'/n for n in ['tribes_sse.h','tribes_sse.llinc','llasm_cpu.h']];r={'pass':True,'state':'finished','cases':65536,'original_pc':'0x100c5bdc','original_bytes_hex':code.hex(),'original_constant_address':'0x10143a00','original_constant_hex':constant.hex(),'original_image_sha256':sha(original),'sources_sha256':{str(p.relative_to(R)):sha(p) for p in paths},'srw_sha256':sha(srw),'patch_sha256':build['patch_sha256'],'llasm_sha256':sha(llasm),'fixture_sha256':sha(out/'fixture.exe'),'relocations_sha256':sha(out/'relocations.csv'),'emitted_body_sha256':sha(source),'ir_sha256':sha(ir),'binary_sha256':sha(exe),'sse_math':math['evidence'],'output':run.stdout.strip(),'scope':'Relocation-bearing original MADDWD bytes and32-byte PE constant mapped to guarded unaligned host data. FullCPU/flags/allMXCSR; no complete DLL mapping/initialization or gameplay proof.'};(out/'result.json').write_text(json.dumps(r,indent=2)+'\n');print(run.stdout.strip())
